  .trim(),

    location: job.location,

    skills: job.tags || [],

    salary: null,

    created_at: job.date || new Date().toISOString(),

    apply_url: job.url
  }
}));

function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (h << 5) - h + str.charCodeAt(i);
    h |= 0;
  }
  return h.toString();
}

function computeQuality(job) {
  let score = 0;

  const title = job.title || "";
  const desc = job.description || "";
  const skills = job.skills || [];

  // Has meaningful title
  if (title.length > 5) score += 10;

  // Has description
  if (desc.length > 200) score += 20;

  // Has skills extracted
  if (skills.length > 0) score += 25;

  // Has company name
  if (job.company) score += 10;

  // Good structured job post
  if (desc.includes("experience") || desc.includes("responsibilities")) {
    score += 15;
  }

  // Bonus: remote jobs
  if ((job.location || "").toLowerCase().includes("remote")) {
    score += 10;
  }

  return Math.min(score, 100); // cap at 100
}

return items.map(item => {
  const j = item.json;

  const raw = `${j.title}|${j.company}|${j.location}|${j.source}|${j.apply_url}`;

  return {
    json: {
      ...j,
      job_hash: hash(raw),
      quality_score: computeQuality(j)
    }
  };
});

const users = $('Fetch Users Data').all();
const jobs = $('Fetch Recent High-Quality Jobs').all();

const output = [];

for (const u of users) {
  for (const j of jobs) {
    output.push({
      json: {
