return output;

const items = $input.all();

const output = [];

for (const item of items) {
  const { user, job } = item.json;

  function norm(arr = []) {
    return arr.map(s =>
      (s || "")
        .toLowerCase()
        .replace(/\s+/g, "")
        .trim()
    );
  }

  const userSkills = norm(user.skills);
  const jobSkills = norm(job.skills);

  let matchCount = 0;

  for (const s of jobSkills) {
    if (userSkills.some(u => u.includes(s) || s.includes(u))) {
      matchCount++;
    }
  }

  const skillScore =
    jobSkills.length > 0 ? matchCount / jobSkills.length : 0;

  const locationScore =
    job.location === "Remote" ||
    job.location?.toLowerCase().includes(
      user.preferred_location?.split(",")[0].toLowerCase()
    )
      ? 1
      : 0.3;

  let expScore = 5;
  if (user.experience_years >= 5) expScore = 15;
  else if (user.experience_years >= 2) expScore = 10;

  const quality = (job.quality_score || 0) / 100;

  const score =
    skillScore * 50 +
    locationScore * 20 +
    expScore +
    quality * 20;

  output.push({
    json: {
      user_id: user.id,
      job_id: job.job_hash,
      fit_score: Math.round(score),
      skill_score: skillScore,
      quality_score: job.quality_score
    }
  });
}

return output;

const items = $input.all();

const MIN_SCORE = 60; // adjust as needed (start with 50–60)

const output = [];

const seen = new Set();

for (const item of items) {
  const m = item.json;

  // 1. FILTER LOW QUALITY MATCHES
  if (!m.fit_score || m.fit_score < MIN_SCORE) {
    continue;
  }

  // 2. DEDUPLICATION KEY (important)
  const key = `${m.user_id}_${m.job_id}`;

  if (seen.has(key)) continue;
  seen.add(key);

  // 3. CLEAN OUTPUT FORMAT FOR DB
  output.push({
    json: {
      user_id: m.user_id,
      job_id: m.job_id,
      fit_score: Math.round(m.fit_score),
      skill_score: m.skill_score || 0,
      quality_score: m.quality_score || 0,
      notified: false
    }
  });
}

return output;

